    private fun deserializeGroups(json: String): List<FocusGroup> {
        return try {
            val jsonArray = JSONArray(json)
            val groups = mutableListOf<FocusGroup>()
            for (i in 0 until jsonArray.length()) {
                val obj = jsonArray.getJSONObject(i)
                val soundsArray = obj.getJSONArray("sounds")
                val sounds = mutableListOf<String>()
                for (j in 0 until soundsArray.length()) {
                    sounds.add(soundsArray.getString(j))
                }
                groups.add(
                    FocusGroup(
                        id = obj.getString("id"),
                        name = obj.getString("name"),
                        icon = Icons.Filled.GraphicEq,
                        sounds = sounds
                    )
                )
            }
            groups
        } catch (_: Exception) {
